def roman_to_int(s):
    v={'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000};t=0
    for i,c in enumerate(s):
        t+= -v[c] if i+1<len(s) and v[s[i+1]]>v[c] else v[c]
    return t

